def add(title,sub,body=None,chart=None,note='',figure=None):slides.append(dict(title=title,subtitle=sub,body=body or [],chart=chart,notes=note,figure=figure))
def chart(xlabel,ylabel,series_,kind='scatter',categories=None):return dict(xlabel=xlabel,ylabel=ylabel,series=series_,kind=kind,categories=categories)
def curves(g,field):return [series(n,range(1,65),df[(df.geometry==g)&(df.strategy==st)][field],c) for st,n,c in zip(strategies,names,C)]
