add('Loss and drift soften the scaling advantage','100 m links, 10 dB source cap, 10 mrad phase jitter and 0.05 mK shared residual',chart=chart('Number of sensors M','Total 1 s RMSE (mg/kg)',curves('pilot','controlled_rmse')),body=['More sensors add probe power. The quantum source reaches its cap at 21 nodes.','Curves describe differential precision under the specified engineering assumptions.'],note='results/scaling.csv, geometry=pilot. Assumed detector 95%, sample 90%, coupling 90%, 0.05 dB excess per splitter stage. Fiber 0.18 dB/km from Corning S9.',figure='01_scaling')
add(f'The 16-node pilot reduces total error by {(1-1/gain)*100:.0f}%','One-second estimates, same 160 nW total launched probe power',chart=chart('Probe strategy','RMSE (mg/kg)',[series('Optical error',range(3),[pilot[x]['optical_rmse'] for x in strategies],'#38bdf8'),series('Total error',range(3),[pilot[x]['controlled_rmse'] for x in strategies],'#2dd4bf')],kind='bar',categories=names),body=[f'Total RMSE: 0.092 → 0.066 mg/kg; {gain:.2f}× precision gain.',f'Independent squeezers reach 0.080 mg/kg: the distributed configuration adds a further {(1-pilot["entangled"]["controlled_rmse"]/pilot["separable"]["controlled_rmse"])*100:.0f}% reduction.'],note='results/summary.json pilot16. No measured-field accuracy claim. Common residual 50 microkelvin is an ambitious compensated bench target.')
